"""A dependency-free, accessible workspace. Untrusted data is rendered with textContent."""
PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>记忆工作台 · Memory Agent</title>
<style>
:root{color-scheme:light;--paper:#f5f3ed;--card:#fffefa;--ink:#202c27;--muted:#56635c;--green:#275c47;--line:#d6dcd1;--error:#9c3428;--gold:#6f531c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}button,input,textarea,select{font:inherit}button,a,input,textarea,select{outline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #8a661c}a{color:var(--green)}button{cursor:pointer;border:1px solid var(--green);border-radius:6px;padding:8px 15px;background:var(--green);color:white;font-weight:600}button:disabled{opacity:.55;cursor:wait}.secondary{background:transparent;color:var(--green)}.danger{background:transparent;color:var(--error);border-color:#d8b3a9}.small{font-size:13px;padding:5px 10px}input,select,textarea{width:100%;border:1px solid #a9b8ac;border-radius:5px;padding:9px 11px;color:var(--ink);background:white}textarea{min-height:100px;resize:vertical}label{display:block;font-size:14px;font-weight:600;margin:12px 0 5px}h1,h2,h3,p{margin:0}h1{font:600 34px/1.3 "Songti SC","STSong",serif;letter-spacing:.03em}h2{font-size:21px}h3{font-size:16px}header{max-width:1220px;margin:auto;padding:34px 28px 20px;display:flex;justify-content:space-between;align-items:flex-end;gap:20px}header p{margin-top:9px;color:var(--muted)}nav{display:flex;gap:18px;font-size:14px;white-space:nowrap}main{max-width:1220px;margin:auto;padding:0 28px 40px}.notice{border-left:3px solid #b69a55;background:#eee9db;padding:11px 16px;font-size:14px}.toolbar{display:flex;align-items:end;gap:16px;padding:12px 0 22px}.toolbar>div{width:150px}.health{font-size:13px;color:var(--muted);margin-left:auto;padding-bottom:8px}.layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(340px,.9fr);gap:24px;align-items:start}.panel{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:24px;margin-bottom:20px}.subtitle{font-size:14px;color:var(--muted);margin-top:5px}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.actions{margin-top:14px}.examples{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.examples button{font-size:12px;background:var(--paper);color:var(--muted);border-color:var(--line);padding:4px 9px}.status{font-size:14px;margin-top:12px;white-space:pre-wrap;overflow-wrap:anywhere}.status.error{color:var(--error)}.status:empty{display:none}details{margin-top:12px}summary{cursor:pointer;font-size:14px;color:var(--muted)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.answer{margin-top:20px;border-top:1px solid var(--line);padding-top:18px}.answer-text{font-size:18px;white-space:pre-wrap;overflow-wrap:anywhere}.meta{font-size:12px;color:var(--muted);margin-top:9px}.evidence{margin-top:12px;padding:12px 14px;background:var(--paper);border-left:3px solid #92ad9b;font-size:14px;overflow-wrap:anywhere}.list-head{display:flex;justify-content:space-between;align-items:center}.memory{padding:18px 0;border-bottom:1px solid var(--line)}.memory:last-child{border-bottom:0}.memory p{margin:7px 0;overflow-wrap:anywhere}.memory-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:10px}.tag{display:inline-block;font-size:12px;background:#e5eee5;color:var(--green);padding:2px 7px;border-radius:3px}.history{padding-left:17px;font-size:14px}.history li{padding:7px 0}.superseded{color:#68716c}.empty{padding:25px 0;color:var(--muted);font-size:14px}.steps{font-size:13px;margin-top:12px;padding-left:22px}.steps li{padding:3px 0}.connect{background:#f0f3ed}.connect .row{align-items:end}.connect label{flex:1}.hidden,[hidden]{display:none!important}footer{font-size:12px;color:var(--muted);max-width:1220px;margin:0 auto;padding:0 28px 30px}@media(max-width:800px){header{align-items:start;padding:22px 18px 18px}h1{font-size:28px}header nav{display:none}main{padding:0 18px 25px}.layout{grid-template-columns:1fr}.panel{padding:18px}.toolbar{flex-wrap:wrap}.health{width:100%;margin:0;padding:0}.grid2{grid-template-columns:1fr}footer{padding:0 18px 22px}}
</style></head><body>
<header><div><h1>记忆工作台</h1><p>记住变化，也说清依据。</p></div><nav><a href="/docs" target="_blank" rel="noopener">接口文档</a><a href="/readyz" target="_blank" rel="noopener">服务状态</a></nav></header>
<main>
<div id="modeNotice" class="notice" role="status">正在读取运行模式…</div>
<section id="authPanel" class="panel connect" hidden aria-labelledby="authHeading"><h2 id="authHeading">连接你的记忆空间</h2><p class="subtitle">输入服务管理员提供的访问令牌。令牌仅在本页内存中使用，刷新后清除。</p><form id="authForm" class="row"><label for="token">访问令牌<input id="token" type="password" autocomplete="off" spellcheck="false" placeholder="粘贴访问令牌"></label><button type="submit">连接</button><button type="button" id="disconnect" class="secondary">断开</button></form><p id="authStatus" class="status" role="status"></p></section>
<div class="toolbar"><div><label for="space">记忆空间</label><select id="space"><option value="work">工作</option><option value="life">生活</option></select></div><span id="owner" class="meta"></span><span id="health" class="health" role="status">检查服务状态…</span></div>
<div class="layout"><div>
<section class="panel" aria-labelledby="writeTitle"><h2 id="writeTitle">记下一件事</h2><p class="subtitle">直接告诉我新信息，或更新之前的安排。</p><form id="writeForm"><label for="content">这次想记住什么</label><textarea id="content" required maxlength="8000" placeholder="例如：星河科技二面安排在2026-11-03下午"></textarea><div class="examples"><button type="button" id="exampleNew">填入面试安排</button><button type="button" id="exampleChange">填入改期消息</button></div><details><summary>记录时间与会话</summary><div class="grid2"><label for="occurredAt">这条消息发生于<input id="occurredAt" type="datetime-local"></label><label for="session">会话名称<input id="session" maxlength="120" value="interview-demo"></label></div><p class="subtitle">时间留空使用现在；同一段对话使用相同会话名称。</p></details><div class="row actions"><button id="writeButton" type="submit">保存记忆</button><button type="button" id="checkJob" class="secondary" hidden>继续检查任务</button><button type="button" id="retryJob" class="secondary" hidden>重新处理</button></div></form><p id="writeStatus" class="status" role="status" aria-live="polite"></p></section>
<section class="panel" aria-labelledby="questionTitle"><h2 id="questionTitle">问一问记忆</h2><p class="subtitle">普通问答检索后作答；追查依据还会查询历史和来源。</p><form id="questionForm"><label for="question">你的问题</label><input id="question" required maxlength="2000" placeholder="星河科技二面什么时候？"><div class="grid2"><label for="method">回答方式<select id="method"><option value="recall">普通问答</option><option value="investigate">追查依据（Agent）</option></select></label><label for="asOf">查看哪个时间的记忆<input id="asOf" type="datetime-local"></label></div><p class="subtitle">历史时间留空时查询当前有效记忆。</p><div class="actions"><button id="askButton" type="submit">提问</button></div></form><p id="askStatus" class="status" role="status" aria-live="polite"></p><div id="answer" class="answer" hidden></div></section>
</div><aside class="panel" aria-labelledby="memoriesTitle"><div class="list-head"><h2 id="memoriesTitle">你记得我什么</h2><button id="refresh" type="button" class="secondary small">刷新</button></div><p id="memoryCount" class="subtitle">每条记忆都保留出处和变更历史。</p><p id="memoryStatus" class="status" role="status" aria-live="polite"></p><div id="memories"><p class="empty">先在左侧保存一条信息，再来查看记忆。</p></div></aside></div>
</main><footer>删除会移除所选记忆的全部版本；同一段对话产生的其他记忆会单独提示。</footer>
<script>
'use strict';
const $=id=>document.getElementById(id);
let accessToken='', currentJob=null, requestGeneration=0, modelMode='demo';
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;}
function status(id,message,error=false){$(id).textContent=message;$(id).classList.toggle('error',error);}
function timestamp(v){if(!v)return '至今';const d=new Date(v);return isNaN(d)?v:d.toLocaleString('zh-CN',{hour12:false});}
function headers(){return {'Content-Type':'application/json',...(accessToken?{'Authorization':'Bearer '+accessToken}:{})};}
async function api(path,method='GET',body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);try{const r=await fetch(path,{method,headers:headers(),body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});let data;try{data=await r.json();}catch{throw Error('服务返回了无法读取的结果，请检查服务状态。');}if(!r.ok){let message=typeof data.detail==='string'?data.detail:r.status===422?'输入格式不正确，请检查时间和内容。':'请求未完成，请稍后重试。';throw Error(message);}return data;}catch(e){if(e.name==='AbortError')throw Error('请求等待超时，请检查任务状态后再操作。');if(e instanceof TypeError)throw Error('无法连接服务，请检查服务是否已启动。');throw e;}finally{clearTimeout(timer);}}
async function refreshHealth(){try{const r=await fetch('/readyz'),d=await r.json();$('health').textContent=d.ok?'服务已就绪':'未就绪：'+Object.entries(d.checks||{}).filter(([,v])=>!v).map(([k])=>({database:'数据库',worker:'后台处理',model:'模型配置',auth:'访问配置'}[k]||k)).join('、');}catch{$('health').textContent='无法连接服务';}}
function clearPrivate(){requestGeneration++;currentJob=null;$('memories').replaceChildren(node('p','连接后查看你的记忆。','empty'));$('memoryCount').textContent='每条记忆都保留出处和变更历史。';$('answer').replaceChildren();$('answer').hidden=true;$('owner').textContent='';$('checkJob').hidden=true;$('retryJob').hidden=true;$('writeButton').disabled=false;$('askButton').disabled=false;$('retryJob').disabled=false;for(const id of ['writeStatus','askStatus','memoryStatus','authStatus'])status(id,'');}
async function loadMemories(){const gen=requestGeneration,space=$('space').value;try{const data=await api('/memories?space='+space);if(gen!==requestGeneration)return;const box=$('memories');box.replaceChildren();$('memoryCount').textContent=data.memories.length+' 条记忆 · '+(space==='work'?'工作':'生活');for(const item of data.memories){const m=item.current,card=node('article',undefined,'memory');card.append(node('h3',m.subject+' · '+m.predicate),node('p',m.fact_text));const row=node('div',undefined,'memory-footer');row.append(node('span','#'+m.memory_id+' · 最新版本','tag'));const del=node('button','删除','danger small');del.type='button';del.addEventListener('click',()=>removeMemory(m.memory_id,del));row.append(del);card.append(row);const details=node('details');details.append(node('summary','查看来源与 '+item.versions.length+' 个版本'));const history=node('ol',undefined,'history');for(const v of item.versions){const li=node('li',undefined,v.status==='active'?'':'superseded');li.append(node('strong',(v.status==='active'?'最新版本':'旧版本')+' #'+v.memory_id),node('p',v.fact_text),node('p','有效时间：'+timestamp(v.valid_from)+' — '+timestamp(v.valid_to),'meta'));for(const s of v.sources||[])li.append(node('p','来源：'+s.session_id+' / 第 '+s.turn_idx+' 轮 · '+timestamp(s.occurred_at)+(s.excerpt?'\n“'+s.excerpt+'”':'（来源正文已删除）'),'meta'));history.append(li);}details.append(history);card.append(details);box.append(card);}if(!data.memories.length)box.append(node('p','这个空间还没有记忆。保存一条信息后，后台会提取其中的事实。','empty'));status('memoryStatus','');}catch(e){if(gen===requestGeneration)status('memoryStatus',e.message,true);}}
async function connect(){const gen=requestGeneration;try{const d=await api('/me');if(gen!==requestGeneration)return;$('owner').textContent='当前身份：'+d.owner;status('authStatus','已连接');await loadMemories();}catch(e){if(gen!==requestGeneration)return;status('authStatus',e.message,true);status('memoryStatus',e.message,true);}}
$('authForm').addEventListener('submit',async e=>{e.preventDefault();clearPrivate();accessToken=$('token').value.trim();$('token').value='';await connect();});
$('disconnect').addEventListener('click',()=>{accessToken='';$('token').value='';clearPrivate();status('authStatus','已断开，令牌已清除。');});
$('space').addEventListener('change',()=>{clearPrivate();connect();});
$('refresh').addEventListener('click',()=>{loadMemories();refreshHealth();});
$('exampleNew').addEventListener('click',()=>{$('content').value='星河科技二面安排在2026-11-03下午';$('question').value='星河科技二面什么时候？';});
$('exampleChange').addEventListener('click',()=>{$('content').value='星河科技二面改到2026-11-05下午';$('question').value='星河科技二面什么时候？';});
async function pollJob(){if(!currentJob)return;const jid=currentJob,gen=requestGeneration;const current=()=>gen===requestGeneration&&currentJob===jid;$('checkJob').hidden=true;$('retryJob').hidden=true;try{for(let i=0;i<90;i++){if(!current())return;const j=await api('/jobs/'+jid);if(!current())return;if(j.status==='done'){status('writeStatus','已保存并完成提取。'+(j.result?.ops?.length?'生成 '+j.result.ops.length+' 项记忆变更。':'这条信息没有产生新的记忆。'));await loadMemories();return;}if(j.status==='dead'||j.status==='cancelled'){status('writeStatus',j.status==='dead'?'后台处理失败，重试次数已用尽。请先检查模型配置，然后重新处理。':'任务已取消。',true);$('retryJob').hidden=j.status!=='dead';return;}status('writeStatus','任务 #'+jid+'：'+(j.status==='running'?'正在整理记忆…':'等待后台处理…')+(j.attempts?'（第 '+j.attempts+' 次尝试）':''));await new Promise(r=>setTimeout(r,1000));}if(!current())return;$('checkJob').hidden=false;status('writeStatus','任务仍在处理，可稍后继续检查；不需要重复提交。');}catch(e){if(!current())return;status('writeStatus',e.message,true);$('checkJob').hidden=false;}}
$('writeForm').addEventListener('submit',async e=>{e.preventDefault();const gen=requestGeneration;$('writeButton').disabled=true;try{const raw=$('content').value.trim();if(!raw)throw Error('请先输入要记录的信息。');const r=await api('/episodes','POST',{space:$('space').value,session_id:$('session').value.trim()||'interview-demo',content:raw,occurred_at:$('occurredAt').value?new Date($('occurredAt').value).toISOString():new Date().toISOString()});if(gen!==requestGeneration)return;currentJob=r.job_id;status('writeStatus',r.duplicate?'这条信息已记录，正在检查处理状态…':'信息已接收，正在整理…');await pollJob();}catch(e){if(gen!==requestGeneration)return;status('writeStatus',e.message,true);if(currentJob)$('checkJob').hidden=false;}finally{if(gen===requestGeneration)$('writeButton').disabled=false;}});
$('checkJob').addEventListener('click',()=>pollJob());
$('retryJob').addEventListener('click',async()=>{const gen=requestGeneration,jid=currentJob;if(!jid)return;$('retryJob').disabled=true;try{await api('/jobs/'+jid+'/retry','POST');if(gen!==requestGeneration||currentJob!==jid)return;await pollJob();}catch(e){if(gen===requestGeneration&&currentJob===jid)status('writeStatus',e.message,true);}finally{if(gen===requestGeneration&&currentJob===jid)$('retryJob').disabled=false;}});
function toolStepText(step){if(!step||typeof step!=='object')return String(step||'工具执行记录');const actions={search_memories:['检索记忆','条记忆','未找到记忆'],get_memory_history:['查看旧版本','个旧版本','暂无旧版本'],get_source_evidence:['读取来源','条来源','暂无来源']};const [action,unit,empty]=actions[step.tool]||['执行工具','条结果','暂无结果'];const memory=step.memory_id===undefined?'':' · 记忆 #'+step.memory_id;const result=step.status==='denied'?'无权限':step.status&&step.status!=='ok'?'未完成':step.count===0?empty:Number.isInteger(step.count)?'找到 '+step.count+' '+unit:'已完成';return action+memory+'：'+result;}
function renderAnswer(r){const box=$('answer');box.replaceChildren();box.hidden=false;box.append(node('p',r.answer,'answer-text'));const ids=r.used_memory_ids||[];box.append(node('p',(r.abstain?'信息不足，已弃答':'引用记忆：'+ids.map(i=>'#'+i).join('、'))+(r.latency_ms?.total!==undefined?' · '+r.latency_ms.total+' ms':''),'meta'));for(const m of r.memories||[]){if(!ids.includes(m.memory_id))continue;box.append(node('p','#'+m.memory_id+' '+m.fact_text,'evidence'));}if(r.steps?.length){const details=node('details');details.append(node('summary','查看 '+r.steps.length+' 次工具执行记录'));const list=node('ol',undefined,'steps');for(const step of r.steps)list.append(node('li',toolStepText(step)));details.append(list);const raw=node('details');raw.append(node('summary','原始记录'),node('pre',JSON.stringify(r.steps,null,2),'meta status'));details.append(raw);box.append(details);}if(r.usage)box.append(node('p',(modelMode==='demo'?'演示模型的统计，不代表真实模型费用。 ':'')+'输入 '+(r.usage.input_tokens||0)+' / 输出 '+(r.usage.output_tokens||0)+' tokens','meta'));}
$('questionForm').addEventListener('submit',async e=>{e.preventDefault();const gen=requestGeneration;$('askButton').disabled=true;status('askStatus','正在查找依据…');try{const body={space:$('space').value,question:$('question').value.trim()};if($('asOf').value)body.as_of=new Date($('asOf').value).toISOString();const r=await api('/'+$('method').value,'POST',body);if(gen!==requestGeneration)return;renderAnswer(r);status('askStatus','');}catch(e){if(gen===requestGeneration)status('askStatus',e.message,true);}finally{if(gen===requestGeneration)$('askButton').disabled=false;}});
async function removeMemory(id,button){if(!confirm('删除这条记忆的全部版本及来源正文？同一对话产生的其他记忆会保留，并在结果中列出。此操作不可恢复。'))return;const gen=requestGeneration;button.disabled=true;try{const r=await api('/memories/'+id,'DELETE');if(gen!==requestGeneration)return;const siblings=r.scope?.sibling_facts_kept||[];await loadMemories();if(gen!==requestGeneration)return;status('memoryStatus',(r.result==='verified'?'已删除，删除验证通过。':'已执行删除，但残留验证未通过，请检查结果。')+(siblings.length?' 同一对话的其他记忆仍保留：'+siblings.map(i=>'#'+i).join('、')+'。如需忘掉整件事，请一并删除。':''),r.result!=='verified');$('answer').hidden=true;}catch(e){if(gen!==requestGeneration)return;status('memoryStatus',e.message,true);button.disabled=false;}}
(async()=>{try{const info=await api('/info');modelMode=info.model_mode;$('modeNotice').textContent=info.model_mode==='demo'?'演示模式：使用确定性规则与模型替身，不调用真实大模型。可用下方样例体验保存、改期、引用和删除。':'真实模型模式：调用 DeepSeek，结果可能有误，请结合来源核对。';$('authPanel').hidden=info.auth_mode!=='token';if(info.auth_mode==='token')status('memoryStatus','输入访问令牌后加载记忆。');else await connect();if(!info.model_configured)status('writeStatus','尚未配置真实模型密钥，记录后的提取任务会失败。',true);}catch(e){$('modeNotice').textContent=e.message;}await refreshHealth();})();
</script></body></html>'''
